import pytest

from flask import json


def test_default_decoder_not_passed_to_loads(app, app_ctx, monkeypatch):
    """When using the default JSONDecoder, cls should not be passed to
    json.loads, so that PyPy can use its fast path.
    """
    original_loads = _json.loads
    call_kwargs = {}

    def tracking_loads(s, **kwargs):
        call_kwargs.update(kwargs)
        return original_loads(s, **kwargs)

    monkeypatch.setattr(_json, "loads", tracking_loads)

    # Use the default decoder (app.json_decoder is JSONDecoder by default)
    json.loads('{"hello": "world"}')

    # cls should not be in the kwargs passed to json.loads
    assert "cls" not in call_kwargs, (
        f"cls={call_kwargs['cls']} was passed to json.loads, "
        "but the default decoder should not set cls"
    )


def test_custom_decoder_passed_to_loads(app, app_ctx, monkeypatch):
    """When using a custom JSONDecoder, cls should be passed to json.loads."""
    class MyDecoder(json.JSONDecoder):
        pass

    app.json_decoder = MyDecoder

    original_loads = _json.loads
    call_kwargs = {}

    def tracking_loads(s, **kwargs):
        call_kwargs.update(kwargs)
        return original_loads(s, **kwargs)

    monkeypatch.setattr(_json, "loads", tracking_loads)

    json.loads('{"hello": "world"}')

    assert "cls" in call_kwargs, (
        "cls was not passed to json.loads, but a custom decoder was set"
    )
    assert call_kwargs["cls"] is MyDecoder"}
